// Refreshes src/disposable-domains.ts, the vendored list of public disposable-inbox domains that list hygiene
// (src/list-hygiene.ts) flags, from github.com/disposable-email-domains/disposable-email-domains (CC0).
// Usage, from api/: node --import tsx scripts/update-disposable-domains.ts [commit-or-branch]   (default: main)
// Commit the regenerated file: Nightmail never fetches the list at runtime. A new list changes HYGIENE_VERSION, so the
// hourly classification pass (classifyContacts) reclassifies every contact against it.
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const REPO = 'disposable-email-domains/disposable-email-domains';
const ref = process.argv[2] ?? 'main';
const commit = await fetch(`https://api.github.com/repos/${REPO}/commits/${encodeURIComponent(ref)}`, { headers: { accept: 'application/vnd.github+json' } })
  .then(async r => { if (!r.ok) throw new Error(`GitHub ${r.status} for ${ref}`); return ((await r.json()) as { sha: string; commit: { committer: { date: string } } }); });
const url = `https://raw.githubusercontent.com/${REPO}/${commit.sha}/disposable_email_blocklist.conf`;
const text = await fetch(url).then(async r => { if (!r.ok) throw new Error(`${r.status} for ${url}`); return r.text(); });
const NAME = /^(?=.{4,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z][a-z0-9-]{0,61}[a-z0-9]$/;
const domains = [...new Set(text.split('\n').map(line => line.trim().toLowerCase()).filter(line => line && !line.startsWith('#')))].sort();
const bad = domains.filter(d => !NAME.test(d));
if (bad.length) throw new Error(`Unexpected entries: ${bad.slice(0, 5).join(', ')}`);
if (domains.length < 1000) throw new Error(`Only ${domains.length} domains: refusing to replace the list.`);
const lines: string[] = [];
let line = '';
for (const d of domains) {
  if (line && line.length + d.length + 1 > 118) { lines.push(line); line = ''; }
  line = line ? `${line} ${d}` : d;
}
if (line) lines.push(line);
const out = `// Generated by scripts/update-disposable-domains.ts: do not edit by hand.
// Public disposable-inbox domains from https://github.com/${REPO}
// (disposable_email_blocklist.conf at ${commit.sha}, committed ${commit.commit.committer.date}).
// The list is dedicated to the public domain (CC0 1.0 Universal).
export const DISPOSABLE_SOURCE = { repository: 'https://github.com/${REPO}', commit: '${commit.sha}', committedAt: '${commit.commit.committer.date}', domains: ${domains.length} } as const;
export const disposableDomains = \`
${lines.join('\n')}
\`;
`;
const target = fileURLToPath(new URL('../src/disposable-domains.ts', import.meta.url));
writeFileSync(target, out);
console.log(`Wrote ${domains.length} domains from ${commit.sha} to ${target}`);
